import ast

source = "from dataclasses import dataclass\nimport sqlite3\nfrom ports import ForStoringLoans\n"
allowed, names = {"dataclasses", "ports"}, set()
for node in ast.walk(ast.parse(source)):
    if isinstance(node, ast.Import):
        names |= {a.name.split(".")[0] for a in node.names}
    elif isinstance(node, ast.ImportFrom):
        names.add(node.module.split(".")[0])
print(sorted(names - allowed))

from dataclasses import dataclass
@dataclass(frozen=True)
class Loan:
    book_id: str

class Member:
    def __init__(self):
        self._loans = [Loan("b1")]
    loans = property(lambda self: tuple(self._loans))  # read-only view

m = Member()
try:
    m.loans.append(Loan("b2"))
except AttributeError as e:
    print(type(e).__name__, len(m.loans))

def shape_problems(counts):
    unit, integration, e2e = counts
    if not unit >= integration >= e2e >= 1:
        return [f"not a pyramid: unit {unit}, integration {integration}, e2e {e2e}"]
    return []

print(shape_problems((3, 5, 2)))
